ths",lr="52–60",st=S[235],no=S[13],ba=false},{n="Dire Maul",lr="54–60",st=S[235],no=S[13],ba=false},{n=S[332],lr="55–60",st=S[235],no=S[13],ba=false},{n="Blackmaw Hold",lr="55–60",st=S[235],no=S[13],ba=false},{n="Upper Blackrock Spire",lr="56–60",st=S[235],no=S[13],ba=false},{n="Scholomance",lr="58–60",st=S[235],no=S[13],ba=false},{n="Stratholme",lr="58–60",st=S[235],no=S[13],ba=false},{n="Shaper’s Terrace",lr="58–60",st=S[235],no=S[13],ba=false}},professions={{n="Alchemy",b="Mana recovery, elixirs and utility potions.",cv="Pair with Herbalism. Read the actual recipe and use requirement."},{n=S[24],b="Metal weapons, mail armor and utility crafts.",cv="Plate and swords are not Shaman equipment. Mail requires level 40."},{n="Enchanting",b="Gear enhancements and disenchanting.",cv="Check slot restrictions and avoid expensive enchants on temporary gear."},{n="Engineering",b="Explosives, target dummies and other utility devices.",cv="Many devices require Engineering. Guns, ammunition and scopes do not support Shaman attacks."},{n="Herbalism",b="Herbs and related materials.",cv="Gathering income depends on your server and route."},{n=S[12],b="Leather and mail armor, armor kits and bags.",cv="Mail requires level 40. Check recipe availability and binding."},{n="Mining",b="Ore, stone and metals.",cv="Balance detours against leveling time."},{n="Skinning",b="Leather, hides and scales.",cv="Profession choice does not grant armor proficiency."},{n="Cooking",b="Recovery food, drinks and food buffs.",cv="Read the buff and level requirements; not every meal benefits every role."},{n="First Aid",b="Bandages, healing potions and cure items.",cv="Damage can interrupt bandaging. Check use restrictions on each item."},{n="Fishing",b="Fish for food and selected recipes.",cv="Optional; no fixed income or combat bonus is assumed."}},gearBrackets={{b="Quest rewards",no="Quest rewards that fit this spec's stat priority, sorted by quest level. The tooltip names the quest, its level, the ques